// QA shim for the canvas inspector: reuse the locally installed Playwright and
// force the system Chrome channel (the inspector asks for channel:'chromium',
// which is not installed here). System Chrome runs the real GPU in headless mode.
const playwright = require('playwright');
const chromium = new Proxy(playwright.chromium, {
  get(target, key) {
    if (key === 'launch') {
      return (options = {}) => {
        const channel = !options.channel || options.channel === 'chromium' ? 'chrome' : options.channel;
        return target.launch({ ...options, channel });
      };
    }
    const value = target[key];
    return typeof value === 'function' ? value.bind(target) : value;
  },
});
module.exports = { ...playwright, chromium };
